package com.aistock.gateway;
import com.aistock.common.*;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController public class ComparisonApiProxyController {
 private final ComparisonPublicClient client;private final ObjectMapper mapper;
 public ComparisonApiProxyController(ComparisonPublicClient client,ObjectMapper mapper){this.client=client;this.mapper=mapper;}
 @RequestMapping({"/api/v1/comparisons","/api/v1/comparisons/**"})public ResponseEntity<byte[]> proxy(HttpServletRequest request){var path=request.getRequestURI();var method=request.getMethod();if(!ProxyHeaderPolicy.allowed(method,path))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);var allowed=path.endsWith("/options")?Set.of("ids","period"):path.equals("/api/v1/comparisons")&&method.equals("GET")?Set.of("before","upper"):Set.<String>of();if(!allowed.containsAll(request.getParameterMap().keySet())||request.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw new BusinessException("COMPARISON_REQUEST_INVALID","对比查询参数不正确",HttpStatus.UNPROCESSABLE_ENTITY);var query=new LinkedHashMap<String,String>();request.getParameterMap().forEach((k,v)->query.put(k,v[0]));byte[] body=new byte[0];if(method.equals("POST")){try{body=request.getInputStream().readNBytes(2049);}catch(java.io.IOException e){throw new BusinessException("COMPARISON_REQUEST_INVALID","对比请求格式不正确",HttpStatus.UNPROCESSABLE_ENTITY);}if(body.length>2048)throw new BusinessException("COMPARISON_REQUEST_TOO_LARGE","对比请求超过处理上限",HttpStatus.PAYLOAD_TOO_LARGE);}try{var headers=ProxyHeaderPolicy.request(request);var relative=path.substring(8);var response=switch(method){case "GET"->client.get(relative,query,headers);case "POST"->client.post(relative,headers,body);case "OPTIONS"->client.options(relative,headers);default->throw new IllegalStateException();};return ResponseEntity.status(response.getStatusCode()).headers(ProxyHeaderPolicy.response(response.getHeaders())).body(response.getBody());}catch(feign.FeignException e){if(e.status()>=400&&e.status()<500){try{var n=mapper.readTree(e.contentUTF8());if(n.path("code").isTextual()&&n.path("message").isTextual()&&n.path("data").isNull())return ResponseEntity.status(e.status()).contentType(MediaType.APPLICATION_JSON).header("Cache-Control","no-store").body(mapper.writeValueAsBytes(ApiResponse.failure(n.path("code").asText(),n.path("message").asText(),TraceIds.normalize(request.getHeader("X-Trace-Id")))));}catch(java.io.IOException ignored){}}throw unavailable();}catch(RuntimeException e){throw unavailable();}}
 private BusinessException unavailable(){return new BusinessException("COMPARISON_SERVICE_UNAVAILABLE","对比服务暂不可用，请查询原请求状态，已保存记录保留",HttpStatus.SERVICE_UNAVAILABLE);}
}
